pub fn append(a: Vec<i32>, b: i32) -> Vec<i32> {
    let new_len = a
        .len()
        .checked_add(1)
        .expect("input vector too large to append one more element");

    let mut c = Vec::with_capacity(new_len);
    c.extend_from_slice(&a);
    c.push(b);
    c
}

